type Item = { n: number; unit: number; kind: 'MCQ' | 'Short answer' | 'Long answer'; q: string; a: string; choices?: string[]; correct?: number; visual?: 'architecture' | 'timer' | 'serial' | 'interrupt' | 'memory' };

const bank: Item[] = [
{n:1,unit:1,kind:'MCQ',q:'What does “micro” mean in microcontroller?',choices:['Distance between two ICs','Distance between two transistors','Small size of the controller','Distance between two pins'],correct:2,a:'“Micro” refers to the small, integrated size of the controller. A microcontroller places the processor and commonly used resources on one chip.'},
{n:2,unit:1,kind:'MCQ',q:'What is the bit size of the 8051?',choices:['8-bit','4-bit','16-bit','32-bit'],correct:0,a:'The classic 8051 is an 8-bit controller: its ALU and main data path operate on 8-bit values.'},
{n:3,unit:1,kind:'MCQ',q:'Name the architecture and instruction-set style of the 8051.',choices:['Von Neumann + CISC','Harvard + CISC','Von Neumann + RISC','Harvard + RISC'],correct:1,a:'The 8051 uses Harvard-style separate code and data spaces, and its instruction set is commonly classified as CISC.'},
{n:4,unit:1,kind:'MCQ',q:'How many general-purpose I/O ports does the classic 8051 have?',choices:['3','4','5','4 ports, with five pins on the last port'],correct:1,a:'There are four 8-bit ports: P0, P1, P2 and P3. Some pins have alternate functions.'},
{n:5,unit:1,kind:'MCQ',q:'Is ROM used for storing data storage?',choices:['True','False'],correct:0,a:'In the broad sense, true: ROM stores non-volatile information such as firmware and constants. It is not used as ordinary read-write working RAM. The printed question is ambiguous, so explain which meaning of “data storage” you use.'},
{n:6,unit:1,kind:'MCQ',q:'Which pin provides reset in the 8051?',choices:['Pin 1','Pin 8','Pin 11','Pin 9'],correct:3,a:'RST is physical pin 9 on the standard 40-pin DIP 8051. It is active high and must be held high for the required reset interval.'},
{n:7,unit:1,kind:'MCQ',q:'External Access (EA) is used to permit what?',choices:['Peripherals','Power supply','ALE','External program-memory interfacing'],correct:3,a:'EA selects the use of external program memory. With EA low, code fetches come from external program memory; with EA high, internal code memory is used where available, with external memory above its range.'},
{n:8,unit:1,kind:'MCQ',q:'Which companies have manufactured 8051-family controllers?',choices:['Atmel','Philips/NXP','Intel','All of the above'],correct:3,a:'The 8051 architecture originated at Intel and has been implemented by many vendors, including Atmel and Philips/NXP.'},
{n:9,unit:1,kind:'Short answer',q:'What is a microcontroller? How does it differ from a microprocessor?',a:'A microcontroller is a compact computer on one chip, typically combining a CPU, program memory, data RAM, I/O ports, timers and serial interfaces. A microprocessor is mainly a CPU and normally needs external memory and peripheral chips. Therefore a microcontroller is usually smaller, lower-cost and suited to dedicated control; a microprocessor suits larger, expandable computing systems.',visual:'architecture'},
{n:10,unit:1,kind:'Short answer',q:'How many I/O ports does the 8051 have? How can one pin carry data and address?',a:'The classic 8051 has four 8-bit ports (P0–P3). During external memory access, Port 0 is multiplexed: it first carries low address A0–A7, then carries data D0–D7. ALE clocks an external latch (for example, 74HC373) to hold the low address while P0 changes to data. Port 2 supplies the high address byte.' ,visual:'memory'},
{n:11,unit:1,kind:'Short answer',q:'Briefly explain EA, RST and ALE.',a:'EA (pin 31) selects internal/external program-code access. RST (pin 9) is the active-high reset input. ALE (pin 30) is the Address Latch Enable pulse used to latch the low address from multiplexed Port 0 during external memory access.'},
{n:12,unit:1,kind:'Short answer',q:'What is the purpose of PSW? What is DPTR used for?',a:'PSW (Program Status Word) stores arithmetic/status flags such as CY, AC, OV and parity, plus register-bank selection bits RS1:RS0. DPTR is a 16-bit data pointer made from DPH and DPL. It is used for 16-bit addresses, especially external data-memory access with MOVX and code-table access with MOVC.'},
{n:13,unit:1,kind:'Long answer',q:'Compare Von Neumann and Harvard architectures.',a:'Von Neumann stores instructions and data in one memory space and commonly shares one bus, so instruction fetch and data transfer contend for that path. Harvard keeps code and data spaces (and often buses) separate, allowing independent access and different memory technologies. Classic 8051 code and data are separately addressed: program reads use code-fetch/MOVC mechanisms, while internal or external data uses data access/MOVX. This separation helps embedded control, though the exact bus implementation varies by derivative.',visual:'architecture'},
{n:14,unit:1,kind:'Long answer',q:'Draw and explain the 8051 block diagram.',a:'Conceptual signal flow: oscillator/clock → CPU (ALU, instruction decoder, accumulator, B, PSW, PC, DPTR, SP) ↔ internal data RAM/SFRs; the CPU connects to program memory and external-memory bus. Four I/O ports connect the chip to devices. Timers/counters provide delays and event counts; the serial port shifts data; interrupt logic prioritizes internal/external events. The oscillator and reset establish operation. In an exam diagram, draw CPU at the centre, code memory above, RAM/SFR and timers/serial/interrupt blocks below, and P0–P3 at the side.'},
{n:15,unit:1,kind:'Long answer',q:'What are SFRs? Explain any four.',a:'Special Function Registers control the CPU and on-chip peripherals; they occupy the upper internal-data address region and many are bit-addressable. ACC (E0H) holds the main ALU operand/result. B (F0H) supports MUL/DIV and general use. PSW (D0H) stores flags and bank selection. TMOD (89H) configures timer/counter modes. Other examples include TCON, SCON, IE, IP, P0–P3 and DPTR bytes.'},
{n:16,unit:1,kind:'Long answer',q:'What is the crystal used for? Where is it connected? Define clock cycle.',a:'The crystal and oscillator circuit provide a stable timing reference for instruction sequencing, timers and serial-rate generation. It is connected between XTAL1 (pin 19) and XTAL2 (pin 18), with suitable capacitors according to the device datasheet. One clock cycle is one period of the oscillator waveform. In the classic 12-clock 8051, one machine cycle spans 12 oscillator periods; modern 8051 derivatives may use fewer clocks, so identify the chip before calculating.'},
{n:17,unit:1,kind:'Long answer',q:'Explain how microcontrollers help IoT, telematics and telecommunications, using household examples.',a:'An appliance microcontroller reads sensors, applies control logic and drives outputs. An air conditioner measures temperature and cycles compressor/fan; a washing machine sequences motor, water valve and safety interlocks. Add a network module and the controller can report status or accept remote commands (IoT). Telematics combines device data with communication/location, such as a vehicle tracker reporting position and diagnostics. Telecommunications equipment uses controllers to supervise link status, buffering and user-interface functions. The key benefits are low cost, compact size, repeatable real-time response and reduced power.'},
{n:18,unit:2,kind:'MCQ',q:'What does “micro” mean in microcontroller?',choices:['Distance between two ICs','Distance between two transistors','Small size of the controller','Distance between two pins'],correct:2,a:'It refers to the compact scale of the integrated controller.'},
{n:19,unit:2,kind:'MCQ',q:'What is the bit size of the 8051?',choices:['8-bit','4-bit','16-bit','32-bit'],correct:0,a:'The classic 8051 is an 8-bit microcontroller.'},
{n:20,unit:2,kind:'MCQ',q:'“DJNZ R0, label” is how many bytes?',choices:['2','3','1','Cannot be determined'],correct:0,a:'The register form is two bytes: opcode plus relative displacement.'},
{n:21,unit:2,kind:'MCQ',q:'JZ and JNZ test the contents of which register?',choices:['DPTR','B','A','PSW'],correct:2,a:'They test whether the accumulator A is zero (JZ) or non-zero (JNZ).'},
{n:22,unit:2,kind:'MCQ',q:'When CALL executes, what return address is placed on the stack?',choices:['Starting address of the stack','Address immediately after CALL','Address of CALL itself','Next stack-pointer address'],correct:1,a:'The return address points to the instruction immediately following the CALL, so RET can resume there.'},
{n:23,unit:2,kind:'MCQ',q:'How many bytes does LCALL take?',choices:['2','4','3','1'],correct:2,a:'LCALL is 3 bytes: opcode plus a 16-bit destination address.'},
{n:24,unit:2,kind:'MCQ',q:'Are PUSH and POP types of CALL instructions?',choices:['Yes','No','None of these','Cannot be determined'],correct:1,a:'No. PUSH and POP explicitly move a byte to/from the stack; CALL saves a return address and transfers program control.'},
{n:25,unit:2,kind:'MCQ',q:'What is one classic machine-cycle duration at 20 MHz?',choices:['1.085 μs','0.60 μs','0.75 μs','1 μs'],correct:1,a:'For the classic 12-clock core: 12/20 MHz = 0.6 μs. A derivative with a different clocks-per-machine-cycle value gives a different answer.'},
{n:26,unit:2,kind:'MCQ',q:'What does MOV A,05H mean?',choices:['Immediate value 05H is loaded into A','Bit 5 of A is set','A loads the byte stored at direct address 05H','None of these'],correct:2,a:'Without #, 05H is a direct address: A receives the byte stored at internal RAM address 05H. MOV A,#05H would load the literal value 05H. The wording of some printed answer keys confuses the address with the data stored there.'},
{n:27,unit:2,kind:'MCQ',q:'Which addressing mode is used for PUSH/POP stack access?',choices:['Immediate','Direct','Indirect','Register'],correct:2,a:'The stack is addressed indirectly through the Stack Pointer (SP), which is updated by PUSH and POP.'},
{n:28,unit:2,kind:'Short answer',q:'What are direct-addressing instructions?',a:'The instruction contains the address of the operand. Example: MOV A,30H copies the byte at internal RAM address 30H into A; MOV 30H,A stores A there. Direct addressing can also name an SFR such as P1. It is different from immediate addressing, where # introduces a literal constant.'},
{n:29,unit:2,kind:'Short answer',q:'Which instructions access external RAM?',a:'MOVX instructions access external data memory: MOVX A,@DPTR and MOVX @DPTR,A use a 16-bit DPTR; MOVX A,@Ri and MOVX @Ri,A use R0/R1 as the low address, with Port 2 commonly supplying the high address on the classic device.'},
{n:30,unit:2,kind:'Short answer',q:'What happens in MOVC A,@A+DPTR?',a:'The CPU adds unsigned A to the 16-bit DPTR to form a code-memory address, reads the byte from program memory at that address, and places it in A. It is useful for lookup tables stored with program code.'},
{n:31,unit:2,kind:'Short answer',q:'Write an assembly-language algorithm to sort n bytes in ascending order.',a:'Example for eight bytes stored at 30H–37H (ascending bubble sort):\nMOV R7,#07H      ; seven passes\nOUTER: MOV R0,#30H\n       MOV R6,R7  ; comparisons this pass\nINNER: MOV A,@R0\n       MOV R2,A   ; save left byte\n       INC R0\n       MOV A,@R0\n       MOV R3,A   ; save right byte\n       CLR C\n       SUBB A,R2  ; carry means right < left\n       JNC NOSWAP\n       MOV @R0,R2\n       DEC R0\n       MOV @R0,R3\n       INC R0\nNOSWAP: DJNZ R6,INNER\n       DJNZ R7,OUTER\nDONE:  SJMP DONE\nThe inner loop shrinks by one item after each pass. For another n, use n−1 for the first pass count and set the array bounds accordingly. The program sorts unsigned bytes; explain that SUBB plus carry tests the ordering.'},
{n:32,unit:2,kind:'Short answer',q:'Explain branching; describe CJNE, RETI, LJMP and JNZ.',a:'Branch instructions change normal sequential execution. CJNE compares operands and jumps if unequal; it also sets carry when the first unsigned operand is less. RETI returns from an interrupt service routine and signals completion to the interrupt controller. LJMP loads a full 16-bit code address. JNZ branches if accumulator A is non-zero.'},
{n:33,unit:2,kind:'Long answer',q:'Explain 8051 addressing modes with examples.',a:'Immediate: literal, e.g. MOV A,#55H. Register: named Rn, e.g. MOV A,R3. Direct: byte address/SFR, e.g. MOV A,30H. Register-indirect: @R0/@R1, e.g. MOV A,@R0. Relative: signed 8-bit displacement for SJMP/JNZ/DJNZ/CJNE. Absolute: AJMP/ACALL target within the same 2-KB code page. Long: LJMP/LCALL full 16-bit code address. Indexed: MOVC A,@A+DPTR or @A+PC for code-table lookup. Choose by where the operand lives and the range/control-flow requirement.'},
{n:34,unit:2,kind:'Long answer',q:'What are registers and register banks? How are banks organized and selected?',a:'Registers are fast CPU storage locations. In internal RAM, addresses 00H–1FH hold four banks, each with R0–R7: Bank 0 at 00H–07H, Bank 1 at 08H–0FH, Bank 2 at 10H–17H and Bank 3 at 18H–1FH. PSW bits RS1:RS0 select 00, 01, 10 or 11. Reset selects Bank 0. Banks make context changes faster, especially in interrupt routines; save/restore any other registers the routine uses.'},
{n:35,unit:2,kind:'Long answer',q:'Explain 8051 memory organization and external-memory interfacing.',a:'The classic architecture has separate code and data spaces. Code space can reach 64 KB; internal program ROM varies by model and external code uses PSEN. Internal data RAM is 128 bytes in the original 8051, with register banks, bit-addressable RAM and general RAM; SFRs occupy 80H–FFH. External data RAM is addressed with MOVX. For a typical external bus, P0 multiplexes low address/data, ALE latches A0–A7, P2 carries A8–A15, and RD/WR strobe external data memory. EA selects internal/external code use. Draw latch, memory, address/data bus and control strobes.' ,visual:'memory'},
{n:36,unit:2,kind:'Long answer',q:'What is bit-addressable memory? How is it arranged and accessed?',a:'The classic 8051 provides 128 bit-addressable internal RAM bits in byte addresses 20H–2FH (16 bytes × 8), addressed as bit addresses 00H–7FH. The bit-addressable SFR region adds bits for eligible SFRs whose byte addresses are multiples of 8. Use SETB bit, CLR bit, CPL bit, JB/JNB and MOV C,bit. Example: SETB 20H sets bit 0 of RAM byte 20H. Bit addressing is convenient for flags and individual control pins.'},
{n:37,unit:2,kind:'Long answer',q:'Explain the arithmetic instructions of the 8051.',a:'ADD adds a source to A; ADDC also includes carry. SUBB subtracts source and borrow from A. INC increments a byte or DPTR (DPTR only has INC DPTR); DEC decrements a byte. MUL AB produces a 16-bit product in B:A; DIV AB puts quotient in A and remainder in B (division by zero is invalid). DA A adjusts a packed-BCD result after addition. Carry, auxiliary carry and overflow flags are affected as specified per instruction; check the instruction table for exact flags. Example: CLR C; MOV A,#25H; ADD A,#17H produces 3CH.'},
{n:38,unit:2,kind:'Long answer',q:'What are logical instructions? Explain with examples.',a:'Logical operations manipulate bit patterns. ANL performs bitwise AND (mask/clear selected bits), ORL performs OR (set selected bits), XRL performs XOR (toggle/compare bits), CLR clears, CPL complements, and RL/RR/RLC/RRC rotate A. SWAP exchanges A’s nibbles. Example: ANL A,#0FH keeps only the low nibble; ORL P1,#01H sets P1.0; XRL A,#01H toggles bit 0. Use byte or bit forms as permitted by the instruction syntax.'},
{n:39,unit:2,kind:'Long answer',q:'Compare Bank 0 R0–R7 with Bank 1 and store equal/different result in Bank 2.',a:'The printed “R0 to R8” is a typo: each bank has only R0–R7, so this solution compares eight pairs. Bank 0 is 00H–07H, Bank 1 is 08H–0FH, and Bank 2 is 10H–17H. Select Bank 3 for working registers so the source banks stay intact:\nMOV PSW,#18H     ; select Bank 3\nMOV R7,#00H      ; index 0..7\nNEXT: MOV A,R7\n      MOV R0,A    ; point into Bank 0\n      MOV A,@R0\n      MOV B,A     ; save Bank 0 byte\n      MOV A,R7\n      ADD A,#08H\n      MOV R0,A    ; point into Bank 1\n      MOV A,@R0\n      XRL A,B\n      JZ SAME\n      MOV A,#0FFH\n      SJMP SAVE\nSAME: CLR A       ; equal -> 00H\nSAVE: MOV R2,A\n      MOV A,R7\n      ADD A,#10H\n      MOV R0,A    ; point into Bank 2\n      MOV A,R2\n      MOV @R0,A\n      INC R7\n      CJNE R7,#08H,NEXT\nThis stores 00H for equal bytes and FFH for different bytes. If the caller needs its original PSW/registers afterward, save and restore them.'},
{n:40,unit:3,kind:'MCQ',q:'What is the function of SCON?',choices:['Controls SBUF and SMOD','Programs serial framing/control','Controls SMOD','None'],correct:1,a:'SCON configures serial-port mode and status/control bits (SM0/SM1, REN, TB8/RB8, TI/RI). SMOD is in PCON.'},
{n:41,unit:3,kind:'MCQ',q:'Which register bit doubles the baud rate?',choices:['TMOD','PCON','SCON','SBUF'],correct:1,a:'PCON.SMOD doubles the baud rate in serial modes 1, 2 and 3 on the classic 8051.'},
{n:42,unit:3,kind:'MCQ',q:'What converts serial data to parallel and parallel data to serial?',choices:['Timers','Counters','Shift registers','Communication modes'],correct:2,a:'Shift registers perform serial-to-parallel and parallel-to-serial conversion; the UART serial block handles framing and timing.'},
{n:43,unit:3,kind:'MCQ',q:'What is the timer clock source in timer mode?',choices:['A separate crystal only','The controller crystal-derived clock','Software','Programming'],correct:1,a:'In timer mode, the classic 8051 increments the timer from the oscillator-derived machine-cycle clock (typically fosc/12). In counter mode, external transitions are counted.'},
{n:44,unit:3,kind:'MCQ',q:'What maximum delay can be generated with a 22 MHz crystal?',choices:['2978.9 s','0.011 ms','11.63 s','2.97 ms'],a:'The question is underspecified because the answer depends on timer mode, reload strategy and whether delay is extended in software. For a classic 16-bit timer, one overflow is 65,536 × 12/22 MHz ≈ 35.75 ms, so none of the listed values describes that maximum. Treat the printed choices as flawed unless the intended configuration is supplied.'},
{n:45,unit:3,kind:'MCQ',q:'What clock feeds the timer in timer mode?',choices:['External frequency f′','Crystal frequency f','Crystal frequency / 12','External frequency / 12'],correct:2,a:'On the classic 12-clock 8051, timer mode increments once per machine cycle, fosc/12. Newer derivatives may configure a different timer clock.'},
{n:46,unit:3,kind:'MCQ',q:'What does TMOD do?',choices:['Selects timer/counter operating modes','Loads timer count','Stores final result','Interrupts timer'],correct:0,a:'TMOD configures GATE, C/T, M1 and M0 fields for Timer 0 and Timer 1.'},
{n:47,unit:3,kind:'MCQ',q:'Which timer mode supports automatic reload?',choices:['Mode 0','Mode 1','Mode 2','Mode 3'],correct:2,a:'Mode 2 is 8-bit auto-reload: TLx overflows and reloads from THx.'},
{n:48,unit:3,kind:'MCQ',q:'TF1, TR1, TF0 and TR0 belong to which register?',choices:['TMOD','SCON','TCON','SMOD'],correct:2,a:'These timer flags and run-control bits are in TCON.'},
{n:49,unit:3,kind:'MCQ',q:'Which is the correct timer-start sequence?',choices:['Load count, start, monitor, stop','Set TMOD, load count, start, monitor, stop','Set TMOD, start, load count, monitor, stop','None'],correct:1,a:'Configure the mode, preload the timer, start it, wait for overflow, then stop/clear or reload as required.'},
{n:50,unit:3,kind:'Short answer',q:'Briefly explain uses of 8051 timers.',a:'Timers create accurate delays and periodic events, measure pulse width/period, count external events when configured as counters, and generate serial baud rates. Timer overflow can be polled or can request an interrupt.'},
{n:51,unit:3,kind:'Short answer',q:'Give the bit addresses of P0 and P1.',a:'In the classic 8051 SFR map, P0 byte address is 80H and its bit addresses are 80H–87H. P1 is 90H and its bit addresses are 90H–97H. Verify a derivative’s SFR map.'},
{n:52,unit:3,kind:'Short answer',q:'What do M1 and M0 do in TMOD?',a:'Together they select the timer mode: 00 Mode 0 (13-bit), 01 Mode 1 (16-bit), 10 Mode 2 (8-bit auto-reload), 11 Mode 3 (split Timer 0; Timer 1 behavior becomes restricted).'},
{n:53,unit:3,kind:'Short answer',q:'How do you program Timer 1 in Mode 2?',a:'Set Timer 1’s TMOD M1:M0 bits to 10 and choose timer/counter and gate settings. Put the reload value in TH1 and initial count in TL1, clear TF1, set TR1. On overflow TL1 is automatically reloaded from TH1. Poll TF1 or enable its interrupt, then clear/handle the flag as required.'},
{n:54,unit:3,kind:'Short answer',q:'How do you program Timer 0 in Mode 0?',a:'Set Timer 0 M1:M0=00 in TMOD, select timer/counter input, preload its 13-bit count across TH0 and the upper five bits of TL0, clear TF0, set TR0, wait for TF0 (poll or interrupt), then stop and clear/reload it. Confirm the exact 13-bit preload format in the device manual.'},
{n:55,unit:3,kind:'Long answer',q:'How many bit-addressable locations are in internal RAM?',a:'There are 128 bit locations in the bit-addressable RAM area: 16 bytes at 20H–2FH multiplied by 8 bits per byte. The bit-addressable SFR area is separate and adds eligible SFR bits; do not include it when asked specifically for internal RAM.'},
{n:56,unit:3,kind:'Long answer',q:'Name timer SFRs and distinguish program from data memory.',a:'Timer SFRs include TMOD (mode), TCON (run/overflow/external-interrupt control), TH0/TL0 and TH1/TL1 (count bytes), plus IE/IP when enabling/prioritizing timer interrupts. Program memory stores instructions/constants and is read with code-fetch/MOVC; data memory stores variables and is accessed with internal RAM/direct/indirect instructions or external RAM via MOVX. The classic 8051 keeps code and data spaces logically separate.'},
{n:57,unit:3,kind:'Long answer',q:'List the 8051 timer operating modes.',a:'Mode 0 is 13-bit; Mode 1 is 16-bit; Mode 2 is 8-bit auto-reload; Mode 3 splits Timer 0 into two 8-bit timers with special restrictions on Timer 1. C/T selects timer clock versus external event counting. GATE can combine TRx with an external gate input. Always verify derivative-specific behavior.'},
{n:58,unit:3,kind:'Long answer',q:'Explain all eight TMOD bits.',a:'TMOD is split into upper Timer 1 and lower Timer 0 nibbles. In each nibble: GATE=1 lets TRx and INTx pin level jointly control counting; C/T=1 counts external transitions, 0 uses internal timer clock; M1 and M0 select modes 0–3. TMOD is not bit-addressable on the classic 8051. Example Timer 0 Mode 1 timer with no gate uses lower nibble 0001b.'},
{n:59,unit:3,kind:'Long answer',q:'Find timer clock frequency at 11.0592 MHz crystal.',a:'For the classic 12-clock 8051: ftimer = fosc/12 = 11.0592 MHz/12 = 921.6 kHz. Timer tick = 1/921.6 kHz ≈ 1.085 μs. A derivative with a different divider gives a different result.'},
{n:60,unit:3,kind:'Long answer',q:'What does TCON do?',a:'TCON contains timer run bits TR0/TR1 and overflow flags TF0/TF1, plus external interrupt controls IT0/IT1 and flags IE0/IE1. Software sets run bits and configures edge/level triggering; hardware sets overflow/external flags. TCON is bit-addressable on the classic device.'},
{n:61,unit:3,kind:'Long answer',q:'Explain the steps for programming an 8051 timer.',a:'1) Compute the required tick count from target delay and timer tick. 2) Choose a mode and timer/counter source. 3) Load TMOD. 4) Preload THx/TLx; for a 16-bit timer preload = 65,536 − required counts. 5) Clear TFx and set TRx. 6) Poll TFx or enable the interrupt. 7) Stop, clear flag and reload/repeat. For delays longer than one overflow, count multiple overflows or use a periodic interrupt. Account for instruction overhead and oscillator/core variant.',visual:'timer'},
{n:62,unit:3,kind:'Long answer',q:'Explain timer modes with a diagram.',a:'Mode 0: THx plus five TLx bits form a 13-bit counter. Mode 1: THx:TLx form a 16-bit counter. Mode 2: TLx is an 8-bit counter and THx is its reload value. Mode 3 splits Timer 0 into TL0 and TH0 8-bit counters with separate control/flags; Timer 1 is constrained. Draw oscillator/12 → timer increment → THx:TLx → overflow flag TFx; for Mode 2 add THx → reload path back to TLx.',visual:'timer'},
{n:63,unit:3,kind:'Long answer',q:'How can 8051 baud rate be increased?',a:'Choose a higher timer overflow frequency by changing the reload value (for Timer 1 Mode 2, a larger reload means fewer counts to overflow), use serial Mode 2/3 where suitable, and set PCON.SMOD to double the generated rate in relevant modes. State the formula for the chosen mode and crystal frequency; changing baud rate also requires the receiving device to use the same rate. Do not change SCON or SBUF to set SMOD.'},
{n:64,unit:3,kind:'Long answer',q:'Explain timer operation as an event counter.',a:'Set C/T=1 in TMOD. The external T0 (P3.4) or T1 (P3.5) input is sampled; qualifying 1-to-0 transitions increment the timer. Load a starting count, start with TRx and poll/use TFx on overflow. This counts pulses from a sensor or encoder rather than measuring elapsed internal clock periods. Maximum reliable input rate and sampling requirements depend on the device datasheet.'},
{n:65,unit:4,kind:'MCQ',q:'Where does execution go immediately after an enabled interrupt occurs?',choices:['Next ordinary instruction','First instruction of ISR','Fixed interrupt-vector location','Program end'],correct:2,a:'The CPU completes the current instruction and vectors to a fixed interrupt-vector address; the vector commonly contains a jump to the full ISR.'},
{n:66,unit:4,kind:'MCQ',q:'After RETI, where does execution continue?',choices:['Next vector in table','Instruction following the interrupted instruction','Instruction after RETI in memory','Nowhere'],correct:1,a:'RETI restores the saved program counter so execution resumes at the interrupted program’s next instruction.'},
{n:67,unit:4,kind:'MCQ',q:'Which pin carries external interrupt INT0?',choices:['Pin 10','Pin 11','Pin 12','Pin 13'],correct:2,a:'INT0 is P3.2, physical pin 12 on the standard 40-pin package.'},
{n:68,unit:4,kind:'MCQ',q:'How do you enable external interrupt 0 when IE starts at zero?',choices:['EX0=1','EA=1','Either one','EX0=1 and EA=1'],correct:3,a:'Both local enable EX0 and global enable EA must be set.'},
{n:69,unit:4,kind:'MCQ',q:'Which register selects edge- or level-triggered external interrupts?',choices:['TCON','IE','IP','SCON'],correct:0,a:'TCON.IT0 and IT1 select edge-triggered (1) or low-level-triggered (0) operation.'},
{n:70,unit:4,kind:'MCQ',q:'What is a disadvantage of level-triggered interrupt?',choices:['Low level must persist long enough','A still-low input can retrigger after ISR','It is hard to generate','Both B and D express retriggering risk'],correct:1,a:'Best answer: B. If the input remains low when the ISR finishes, the interrupt can be requested again. Option D repeats the same idea as B, so the printed choices are duplicated.'},
{n:71,unit:4,kind:'Short answer',q:'Briefly explain serial-port programming.',a:'Select the serial mode in SCON, set receiver enable REN if receiving, configure baud generation (commonly Timer 1 Mode 2), and start the timer. For transmit, write a byte to SBUF and wait for TI; clear TI before the next byte. For receive, wait for RI, read SBUF and clear RI. Interrupts may replace polling.'},
{n:72,unit:4,kind:'Short answer',q:'What are IE and IP used for?',a:'IE enables individual interrupt sources (EX0, ET0, EX1, ET1, ES) and global interrupts (EA). IP selects high or low priority for each source. A source must be enabled locally and globally to be serviced.'},
{n:73,unit:4,kind:'Short answer',q:'Which registers support serial communication?',a:'SCON configures serial mode and flags, SBUF is the transmit/receive data register, PCON.SMOD affects baud rate, and timer registers (often TMOD/TH1/TCON) generate the baud clock. IE/IP configure serial interrupts and priority.'},
{n:74,unit:4,kind:'Short answer',q:'What is an interrupt signal? Name 8051 interrupt types.',a:'An interrupt is an event request that temporarily redirects the CPU to a service routine. Classic sources are external INT0 and INT1, Timer 0 overflow, Timer 1 overflow and serial-port RI/TI. Some derivatives add more sources.',visual:'interrupt'},
{n:75,unit:4,kind:'Short answer',q:'Describe an RS-232 to 8051 interface.',a:'Use a level-shifter such as MAX232 between the bipolar RS-232 connector and the 8051’s logic-level TXD/RXD pins (P3.1/P3.0). Connect common ground and the charge-pump capacitors specified for the transceiver. Cross TX-to-RX and RX-to-TX. The 8051 UART handles start/data/stop framing; the transceiver converts voltage levels and polarity.',visual:'serial'},
{n:76,unit:4,kind:'Long answer',q:'Explain SCON and its bit assignments.',a:'SCON (98H) bits: SM0/SM1 select serial mode; SM2 supports multiprocessor communication; REN enables reception; TB8/RB8 are ninth transmit/received bits in 9-bit modes; TI indicates transmit completion; RI indicates received byte. Modes 0–3 provide shift-register/UART variants. Set and clear flags in software as required; SBUF is the data register.'},
{n:77,unit:4,kind:'Long answer',q:'Define the following serial-communication terms.',a:'This question is the heading for the definitions in Questions 78–81: RS-232, parallel versus serial communication, simplex/half-duplex/full-duplex, and UART. Use one definition, one key feature and a short example for each term.'},
{n:78,unit:4,kind:'Long answer',q:'Define RS-232.',a:'RS-232 is a serial electrical interface standard defining signal levels, connector/signaling conventions and control lines for point-to-point communication. Its voltage levels are not directly compatible with 8051 logic, so a transceiver such as MAX232 is used. The UART handles the data framing; RS-232 defines the electrical interface.'},
{n:79,unit:4,kind:'Long answer',q:'Compare parallel and serial communication.',a:'Parallel sends several bits simultaneously on multiple data wires, which can be fast over short distances but needs more pins and can suffer skew. Serial sends bits sequentially on fewer wires, reducing wiring and supporting longer links more conveniently, but needs framing/clocking. The 8051 has parallel GPIO and a serial UART.'},
{n:80,unit:4,kind:'Long answer',q:'Define simplex, half-duplex and full-duplex.',a:'Simplex is one-way communication only. Half-duplex allows both directions, but one at a time. Full-duplex allows simultaneous transmission in both directions, usually using separate paths or equivalent channel separation. Examples: broadcast receiver (simplex), walkie-talkie (half), telephone call (full).'},
{n:81,unit:4,kind:'Long answer',q:'What is UART?',a:'A Universal Asynchronous Receiver/Transmitter converts parallel bytes to serial frames and received serial frames back to bytes. Asynchronous UART framing typically has an idle mark, start bit, data bits, optional parity and stop bit(s). Both endpoints must agree on baud rate and frame format. The 8051 serial port provides UART modes.'},
{n:82,unit:4,kind:'Long answer',q:'How is UART baud rate determined and selected on 8051?',a:'In serial Mode 1, baud is commonly generated from Timer 1 Mode 2 overflow: baud ≈ (2^SMOD/32) × timer-overflow rate; for classic 12-clock Timer 1 Mode 2, overflow rate = fosc/[12×(256−TH1)]. Set SMOD in PCON, select SCON mode, load TH1 for the target baud, start TR1 and verify error against the desired standard rate. Modes 2 and 3 use oscillator-derived rates. Exact formulas vary by core.'},
{n:83,unit:4,kind:'Long answer',q:'Relate a 48 MHz crystal to machine cycle and baud rate.',a:'For a classic 12-clock core, machine-cycle frequency = 48/12 = 4 MHz and period = 0.25 μs. For UART Mode 1 using Timer 1 Mode 2, baud ≈ (2^SMOD/32) × fosc/[12×(256−TH1)]. With SMOD=0 this simplifies to 48 MHz/[384×(256−TH1)]. A 48 MHz crystal may exceed the rated oscillator frequency of a classic 8051; check the exact derivative and its divider before applying this example.'},
{n:84,unit:4,kind:'Long answer',q:'Explain serial communication, data framing and the common 8051 frame.',a:'Serial communication transmits bits sequentially. In asynchronous UART, framing lets the receiver find each byte without a shared clock: an idle line is high, a low start bit marks the beginning, data bits follow (commonly 8, least-significant bit first), optional parity may follow, and one or more high stop bits end the frame. The common 8051 UART format is 8 data bits, no parity, one stop bit (8-N-1), typically Mode 1.'},
{n:85,unit:4,kind:'Long answer',q:'What are assembler directives and how do they affect the 8051?',a:'Assembler directives guide the assembler; they are not CPU instructions and do not execute at runtime. ORG sets an assembly address, END marks source end, EQU defines a constant, DB emits bytes, and segment/data directives reserve or locate storage. Directives affect placement and generated machine-code/data layout, not the processor’s execution rules.'},
{n:86,unit:4,kind:'Long answer',q:'Write an assembly approach to transmit your name serially.',a:'Example transmit loop for a crystal of 11.0592 MHz at 9600 baud (classic 8051, Timer 1 Mode 2):\nMOV TMOD,#20H\nMOV TH1,#0FDH\nMOV SCON,#50H  ; UART Mode 1, receiver enabled\nMOV PCON,#00H  ; SMOD=0\nSETB TR1\nMOV DPTR,#MSG\nSEND: CLR A\n      MOVC A,@A+DPTR\n      JZ FINISH\n      MOV SBUF,A\nWAIT: JNB TI,WAIT\n      CLR TI\n      INC DPTR\n      SJMP SEND\nFINISH: SJMP FINISH\nMSG: DB "YOUR NAME",00H\nReplace YOUR NAME with the requested characters. MOVC reads the next character from code memory; SBUF starts transmission; TI signals completion. The TH1 value depends on oscillator frequency and desired baud.'},
{n:87,unit:4,kind:'Long answer',q:'Describe an interrupt-based square wave on P1.0 while transmitting a name.',a:'For a 10 kHz square wave, period T=100 μs; toggle P1.0 every 50 μs. Configure Timer 0 Mode 1, enable ET0 and EA, and use a calculated preload. At 11.0592 MHz on a classic 12-clock core, one tick is about 1.085 μs, so 46 counts is about 49.9 μs (reload FFD2H). The ISR reloads TH0/TL0, toggles P1.0 and returns with RETI. Send the name in the main loop using the SBUF/TI sequence from Q86. Interrupt entry and reload instructions add latency, so adjust the preload for the measured implementation.'},
{n:88,unit:4,kind:'Long answer',q:'Describe an interrupt program for a 10 kHz square wave at P0.1 and storing serial data in Bank 2 R2.',a:'Set Timer 0 for a 50 μs half-period (10 kHz output) and toggle P0.1 in its ISR. Enable the serial interrupt; read SBUF on RI and write the byte to direct RAM address 12H, which is Bank 2 R2. Example serial ISR flow: test RI; if set, MOV A,SBUF; MOV 12H,A; CLR RI; test/clear TI if transmit-complete caused the serial interrupt; RETI. Timer 0 has vector 000BH and serial has vector 0023H, so place LJMP stubs at both vectors. P0.1 is open-drain on the classic 8051: add a pull-up resistor. Compute and then measure timing because ISR overhead shifts the output frequency.'},
{n:89,unit:4,kind:'Long answer',q:'Describe an interrupt program for a 12 kHz square wave at P0.1 and storing received data in Bank 1 R2.',a:'For 12 kHz, T≈83.33 μs and the toggle interval is T/2≈41.67 μs. At an 11.0592 MHz classic 12-clock core, 38 timer counts are ≈41.23 μs; calculate the nearest preload from the chosen mode and account for ISR latency. In the serial ISR, when RI=1, read SBUF and store it at direct address 0AH (Bank 1 R2), clear RI, and return with RETI. Clear TI too if the serial interrupt can also be triggered by transmit completion. Put LJMP stubs at Timer 0 vector 000BH and serial vector 0023H. P0.1 needs a pull-up. State the achieved approximate frequency rather than claiming an exact 12 kHz.'},
{n:90,unit:5,kind:'MCQ',q:'How many rows and columns are in a 16×2 LCD?',choices:['2 rows, 32 columns','16 rows, 2 columns','16×16','2 rows, 16 columns'],correct:3,a:'It has 2 rows with 16 character positions per row.'},
{n:91,unit:5,kind:'MCQ',q:'How many data lines does a typical character LCD have?',choices:['16','8','1','0'],correct:1,a:'A standard HD44780-compatible module exposes D0–D7 (8 data lines), though it can operate in 4-bit mode using D4–D7.'},
{n:92,unit:5,kind:'MCQ',q:'Which LCD pin adjusts contrast?',choices:['Pin 1','Pin 2','Pin 3','Pin 4'],correct:2,a:'Pin 3 (V0/VEE) is the contrast input.'},
{n:93,unit:5,kind:'MCQ',q:'What is required to read from an LCD?',choices:['Low-to-high pulse on E','R/W high','R/W high and an enable pulse','None'],correct:2,a:'Set R/W high, configure the data bus as input, and strobe E while observing setup/hold timing.'},
{n:94,unit:5,kind:'MCQ',q:'Which 8051 signals connect to an 8255?',choices:['RD','WR','D0–D7','All listed'],correct:3,a:'The interface uses the data bus and read/write controls, plus address decoding and chip select.'},
{n:95,unit:5,kind:'MCQ',q:'Why use MOVX for an 8255 in memory-mapped I/O?',choices:['8255 is mapped into external data-memory space','It accesses external communication','It transfers data','It interfaces LCD/motor'],correct:0,a:'If the 8255 is decoded into the 8051 external data-memory address space, MOVX read/write cycles access its ports/control register.'},
{n:96,unit:5,kind:'MCQ',q:'What is the key difference between LM34 and LM35?',choices:['Sensor vs transducer','Fahrenheit vs Celsius scale','Low vs high precision','Calibration required vs not'],correct:1,a:'LM34 output is calibrated in degrees Fahrenheit; LM35 output is calibrated in degrees Celsius.'},
{n:97,unit:5,kind:'MCQ',q:'Why may ADC0848 Vref be set to 2.56 V with an LM35?',choices:['To set ADC full-scale/range and quantization step','Ground the chip','Power the chip','All of these'],correct:0,a:'Vref sets the ADC conversion range and therefore the voltage-per-code step. It is not the ground or supply pin.'},
{n:98,unit:5,kind:'MCQ',q:'How many pins does an LM35 have?',choices:['2','1','3','4'],correct:2,a:'The common LM35 package has supply, output and ground pins.'},
{n:99,unit:5,kind:'Short answer',q:'What is an 8255 used for?',a:'The 8255 Programmable Peripheral Interface expands parallel I/O. It provides three 8-bit ports (A, B, C) configurable in groups and modes, useful for connecting keypads, displays, switches and control electronics.'},
{n:100,unit:5,kind:'Short answer',q:'Name important LCD modules.',a:'Common character modules include 16×2 and 20×4 alphanumeric LCDs; graphical LCDs use pixel-addressed display RAM. Interfaces may be parallel (4/8-bit) or serial through an adapter. State the controller/module datasheet when giving pin or command details.'},
{n:101,unit:5,kind:'Short answer',q:'Explain the 8255 I/O-mode control word.',a:'In I/O mode, D7=1 selects I/O configuration. D6–D5 select Group A mode; D4 selects Port A input/output; D3 selects upper Port C direction; D2 selects Group B mode; D1 selects Port B direction; D0 selects lower Port C direction. A 1 direction bit means input, 0 means output. Draw the bit positions and label each field.'},
{n:102,unit:5,kind:'Short answer',q:'What is the non-volatile RAM capacity inside DS12887?',a:'The DS12887 RTC family provides 114 bytes of battery-backed user RAM in addition to its clock/calendar and control registers. Confirm the exact suffix/datasheet variant.'},
{n:103,unit:5,kind:'Long answer',q:'Define peripherals and interfacing.',a:'A peripheral is an external device that provides input, output, storage, communication or sensing (for example, keypad, LCD, ADC, motor driver or RTC). Interfacing is the hardware and software arrangement that lets the CPU exchange correctly timed and electrically compatible signals with that device. It includes pin mapping, address/chip selection, voltage/current conditioning, protocols, control signals and firmware.'},
{n:104,unit:5,kind:'Long answer',q:'Which ports belong to Group A and Group B of the 8255?',a:'Group A includes Port A (PA7–PA0) and upper Port C (PC7–PC4). Group B includes Port B (PB7–PB0) and lower Port C (PC3–PC0). Port C lines can act as general I/O or handshake/status lines depending on the selected mode.'},
{n:105,unit:5,kind:'Long answer',q:'What is a stepper motor used for? What is an RTC?',a:'A stepper motor moves in discrete angular steps, enabling repeatable position control in printers, small CNC systems and instrumentation. It needs a driver because the 8051 pins cannot supply winding current. An RTC (real-time clock) keeps calendar/time using a crystal and backup supply, often communicating over a bus; it retains time while the main system is off.'},
{n:106,unit:5,kind:'Long answer',q:'Explain interfacing 8051 to external memory.',a:'For external code/data memory, P0 carries multiplexed low address/data. ALE clocks a latch to hold A0–A7; P2 carries A8–A15. PSEN reads external code. RD and WR control external data reads/writes; MOVX addresses external data memory. EA chooses internal/external code use. Add address decoding/chip select and ensure bus timing and voltage compatibility.',visual:'memory'},
{n:107,unit:5,kind:'Long answer',q:'Explain delay generation with an interfacing/timing diagram.',a:'For a timer delay, calculate N = delay / timer_tick; for a 16-bit timer preload is 65,536−N. Load THx:TLx, start the timer, wait for overflow, stop/reload. For repeated delays, use an interrupt. In a waveform diagram, show timer start, count interval, overflow flag and output transition. Include oscillator frequency, core divider, mode and instruction overhead so the result is reproducible.',visual:'timer'},
{n:108,unit:5,kind:'Long answer',q:'Draw and explain the functional blocks of 8255.',a:'The 8255 contains data-bus buffer, read/write control logic, Group A/Group B control, Port A, Port B and two halves of Port C. The bus buffer transfers data to the CPU; control logic decodes chip select, address and RD/WR; group logic configures direction/mode; ports latch input/output. Draw CPU data bus to buffer, control/address to decoder, then three port blocks labelled PA, PB and PC upper/lower.'},
{n:109,unit:5,kind:'Long answer',q:'Explain an opto-isolator interface with the 8051.',a:'An opto-isolator transfers a signal through light while keeping input and output circuits electrically isolated. Drive its LED through a current-limiting resistor from a controller/output circuit; connect the phototransistor side to the isolated load supply with an appropriate pull-up/load. Observe polarity, LED current, CTR and transistor ratings. For inductive loads, add a suitable flyback/protection path. Isolation reduces ground-loop/noise and protects the logic side when designed correctly.'},
{n:110,unit:5,kind:'Long answer',q:'Explain LM35 interfacing with a microcontroller.',a:'Power the LM35 within its specified range and connect ground and analog output to an ADC input (the 8051 has no built-in ADC in the classic version). An ADC such as ADC0848 converts voltage to a digital code; connect data/control lines and start/read signals per its datasheet. LM35 is approximately 10 mV/°C, so temperature °C ≈ Vout/0.010 V. With an 8-bit ADC and Vref=2.56 V, ideal step is 10 mV/code, roughly 1 °C/code; account for offset, quantization and calibration.'},

];

export const qb2024MCQs = bank
  .filter((item) => item.kind === 'MCQ' && item.correct !== undefined)
  .map((item) => ({
    id: 'qb2024-' + item.n,
    unit: item.unit,
    question: item.q,
    options: item.choices ?? [],
    correctIndex: item.correct ?? 0,
    explanationEn: item.a,
    explanationHi: ''
  }));

const units = [
  'Introduction and 8051 architecture',
  'Instruction set and addressing modes',
  'Timers and serial communication',
  'Interrupts and assembly programming',
  'Peripheral interfacing and single-board computers'
];

const diagrams: Record<string, React.ReactNode> = {
  architecture: <div className="grid grid-cols-3 gap-2 items-center text-center text-[11px] sm:text-sm"><div className="rounded-xl border border-white/15 bg-white/5 p-3">Program memory<br/><span className="text-slate-400">instructions</span></div><div className="rounded-xl border border-cyan-300/30 bg-cyan-300/10 p-3 font-bold">8051 CPU<br/><span className="text-slate-400 font-normal">ALU + control</span></div><div className="rounded-xl border border-white/15 bg-white/5 p-3">Data memory<br/><span className="text-slate-400">variables</span></div><div/><div className="text-cyan-200">↕ buses</div><div/><div className="rounded-xl border border-white/15 bg-white/5 p-3">Timers + UART</div><div className="text-cyan-200">↔</div><div className="rounded-xl border border-white/15 bg-white/5 p-3">Ports P0–P3</div></div>,
  memory: <div className="flex flex-wrap items-center justify-center gap-2 text-center text-[11px] sm:text-sm"><div className="rounded-xl border border-white/15 bg-white/5 p-3">P0<br/>A0–A7 then D0–D7</div><span className="text-cyan-200">→</span><div className="rounded-xl border border-amber-300/30 bg-amber-300/10 p-3">ALE latch<br/>holds low address</div><span className="text-cyan-200">→</span><div className="rounded-xl border border-white/15 bg-white/5 p-3">External memory<br/>P2 = A8–A15</div></div>,
  timer: <div className="flex flex-wrap items-center justify-center gap-2 text-center text-[11px] sm:text-sm"><div className="rounded-xl border border-white/15 bg-white/5 p-3">Oscillator<br/>fosc / 12*</div><span className="text-cyan-200">→</span><div className="rounded-xl border border-white/15 bg-white/5 p-3">THx : TLx<br/>counter</div><span className="text-cyan-200">→</span><div className="rounded-xl border border-emerald-300/30 bg-emerald-300/10 p-3">Overflow<br/>TFx = 1</div><span className="text-cyan-200">→</span><div className="rounded-xl border border-white/15 bg-white/5 p-3">Poll or ISR</div><p className="basis-full text-slate-500">*Classic 12-clock 8051; check the specific derivative.</p></div>,
  serial: <div className="flex flex-wrap items-center justify-center gap-2 text-center text-[11px] sm:text-sm"><div className="rounded-xl border border-white/15 bg-white/5 p-3">8051 TXD/RXD<br/>logic levels</div><span className="text-cyan-200">↔</span><div className="rounded-xl border border-violet-300/30 bg-violet-300/10 p-3">MAX232<br/>level conversion</div><span className="text-cyan-200">↔</span><div className="rounded-xl border border-white/15 bg-white/5 p-3">RS-232 device<br/>voltage levels</div></div>,
  interrupt: <div className="flex flex-wrap items-center justify-center gap-2 text-center text-[11px] sm:text-sm"><div className="rounded-xl border border-white/15 bg-white/5 p-3">Event request</div><span className="text-cyan-200">→</span><div className="rounded-xl border border-white/15 bg-white/5 p-3">IE + priority</div><span className="text-cyan-200">→</span><div className="rounded-xl border border-cyan-300/30 bg-cyan-300/10 p-3">Vector → ISR</div><span className="text-cyan-200">→</span><div className="rounded-xl border border-white/15 bg-white/5 p-3">RETI → resume</div></div>,
};

export const QB2024Section: React.FC = () => {
  const [view, setView] = useState<'questions' | 'solutions'>('questions');
  const [unit, setUnit] = useState<number | 'all'>('all');
  const [kind, setKind] = useState<string>('all');
  const [query, setQuery] = useState('');
  const [open, setOpen] = useState<number | null>(1);
  const [practiceMode, setPracticeMode] = useState(false);
  const [practiceItems, setPracticeItems] = useState<Item[]>([]);
  const [practiceIndex, setPracticeIndex] = useState(0);
  const [practiceChoice, setPracticeChoice] = useState<number | null>(null);
  const [practiceScore, setPracticeScore] = useState(0);
  const visible = useMemo(() => bank.filter(x => (unit === 'all' || x.unit === unit) && (kind === 'all' || x.kind === kind) && (!query || (x.q + x.a).toLowerCase().includes(query.toLowerCase()))), [unit,kind,query]);
  const startPractice = () => {
    const pool = bank.filter(item => item.kind === 'MCQ' && item.correct !== undefined);
    for (let i = pool.length - 1; i > 0; i -= 1) {
      const j = Math.floor(Math.random() * (i + 1));
      [pool[i], pool[j]] = [pool[j], pool[i]];
    }
    setPracticeItems(pool.slice(0, 10));
    setPracticeIndex(0);
    setPracticeChoice(null);
    setPracticeScore(0);
    setPracticeMode(true);
  };
  const choosePracticeAnswer = (choice: number) => {
    if (practiceChoice !== null) return;
    setPracticeChoice(choice);
    if (choice === practiceItems[practiceIndex]?.correct) setPracticeScore(prev => prev + 1);
  };
  const nextPracticeQuestion = () => {
    setPracticeChoice(null);
    setPracticeIndex(prev => prev + 1);
  };
  return <section id="qb2024" className="py-12 scroll-mt-20 border-t border-white/10">
    <div className="mb-7">
      <p className="text-xs font-black tracking-widest text-cyan-200 uppercase mb-1">ITV-304 · SESSION 2020–21 · UPDATED SOURCE: 2024 QB</p>
      <h2 className="text-2xl sm:text-3xl font-extrabold">Question Bank 2024</h2>
      <p className="text-sm text-slate-400 mt-2 max-w-3xl">All 110 questions, organized by unit and question type. The separate solved section gives clear English explanations, worked steps and visual guides. Answers follow classic 8051 assumptions unless a derivative is specified.</p>
    </div>
    <div className="flex flex-wrap gap-2 mb-5">
      <a href="#qb2024" onClick={()=>setView('questions')} className={`rounded-xl px-4 py-2 text-sm font-bold border ${view==='questions'?'bg-white text-black border-white':'border-white/15 text-slate-300'}`}><BookOpen className="inline w-4 h-4 mr-2"/>Question Bank</a>
      <a href="#qb2024" onClick={()=>setView('solutions')} className={`rounded-xl px-4 py-2 text-sm font-bold border ${view==='solutions'?'bg-white text-black border-white':'border-white/15 text-slate-300'}`}><CheckCircle2 className="inline w-4 h-4 mr-2"/>Solved QB</a>
      <button type="button" onClick={startPractice} className="rounded-xl px-4 py-2 text-sm font-bold border border-cyan-200/30 bg-cyan-200/10 text-cyan-100 hover:bg-cyan-200/20"><Zap className="inline w-4 h-4 mr-2"/>Practice 10 MCQs</button>
    </div>
    <div className={practiceMode ? "hidden" : "frost-glass rounded-2xl p-4 mb-5"}>
      <div className="flex flex-col lg:flex-row gap-3">
        <label className="relative flex-1"><Search className="absolute left-3 top-3 w-4 h-4 text-slate-500"/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search questions or explanations" className="w-full bg-black/30 border border-white/10 rounded-xl py-2.5 pl-10 pr-3 text-sm text-white outline-none focus:border-cyan-300/40"/></label>
        <select value={unit} onChange={e=>setUnit(e.target.value==='all'?'all':Number(e.target.value))} className="bg-[#10151d] border border-white/10 rounded-xl px-3 py-2 text-sm text-white"><option value="all">All units</option>{units.map((u,i)=><option key={u} value={i+1}>Unit {i+1}: {u}</option>)}</select>
        <select value={kind} onChange={e=>setKind(e.target.value)} className="bg-[#10151d] border border-white/10 rounded-xl px-3 py-2 text-sm text-white"><option value="all">All question types</option><option>MCQ</option><option>Short answer</option><option>Long answer</option></select>
      </div>
      <p className="text-xs text-slate-500 mt-3">Showing {visible.length} of {bank.length} questions · English answers</p>
    </div>
    {!practiceMode && view==='solutions' && <div className="frost-glass rounded-2xl p-4 sm:p-5 mb-5"><h3 className="font-bold text-white mb-2">How to use these model answers</h3><p className="text-sm text-slate-300 leading-relaxed">Start with the direct definition, explain the working in sequence, then draw the labelled signal path where shown. For numerical answers, write the formula, substitute values with units, and state the classic 12-clock-core assumption. The source QB includes a few ambiguous or mistaken prompts; those are explicitly called out in the relevant answer instead of silently changing the question.</p><div className="mt-4 rounded-xl border border-amber-300/20 bg-amber-300/5 p-3 text-xs text-amber-100">Visual guides are conceptual. Pin numbers, timing limits and electrical connections should be checked against the exact 8051 derivative and peripheral datasheets used in your lab.</div></div>}

    {practiceMode && <div className="frost-glass rounded-3xl p-5 sm:p-8 max-w-3xl mx-auto mb-6">
      <div className="flex items-center justify-between gap-4 mb-5">
        <div><p className="text-xs uppercase tracking-widest text-cyan-200 font-bold">RANDOM PRACTICE ROUND</p><h3 className="text-xl font-extrabold mt-1">{practiceIndex < practiceItems.length ? ('Question ' + (practiceIndex + 1) + ' of ' + practiceItems.length) : 'Round complete'}</h3></div>
        <div className="text-sm rounded-xl bg-white/5 border border-white/10 px-3 py-2">Score <strong className="text-cyan-100">{practiceScore}/{practiceItems.length}</strong></div>
      </div>
      <div role="progressbar" aria-label="Practice question progress" aria-valuemin={0} aria-valuemax={practiceItems.length} aria-valuenow={Math.min(practiceIndex + (practiceChoice !== null ? 1 : 0), practiceItems.length)} className="h-1.5 bg-white/10 rounded-full overflow-hidden mb-6"><div className="h-full bg-cyan-200 transition-all" style={{width:(practiceItems.length ? Math.min((practiceIndex + (practiceChoice !== null ? 1 : 0)) / practiceItems.length * 100,100) : 0)+'%'}}/></div>
      {practiceIndex < practiceItems.length ? <div>
        <p className="text-[11px] uppercase tracking-wider text-slate-500 mb-2">Unit {practiceItems[practiceIndex].unit} · QB Q{practiceItems[practiceIndex].n}</p>
        <h4 className="text-lg font-bold leading-relaxed mb-5">{practiceItems[practiceIndex].q}</h4>
        <div className="grid gap-2">{practiceItems[practiceIndex].choices?.map((choice,index)=>{
          const answered=practiceChoice!==null, correct=index===practiceItems[practiceIndex].correct, selected=index===practiceChoice;
          const style=answered?(correct?'border-emerald-300/50 bg-emerald-300/10 text-emerald-100':selected?'border-rose-300/40 bg-rose-300/10 text-rose-100':'border-white/5 text-slate-500'):'border-white/10 bg-white/[0.03] hover:bg-white/[0.08] text-slate-200';
          return <button key={choice} type="button" disabled={answered} onClick={()=>choosePracticeAnswer(index)} className={'rounded-xl border p-3 text-left text-sm transition-colors '+style}>{String.fromCharCode(65+index)}. {choice}{answered&&correct?' ✓':''}</button>;
        })}</div>
        {practiceChoice!==null && <div className="mt-4 rounded-xl border border-white/10 bg-black/20 p-4"><p className={practiceChoice===practiceItems[practiceIndex].correct?'font-bold text-sm mb-1 text-emerald-200':'font-bold text-sm mb-1 text-amber-100'}>{practiceChoice===practiceItems[practiceIndex].correct?'Correct!':'Not quite—review this idea.'}</p><p className="text-sm text-slate-300 leading-relaxed">{practiceItems[practiceIndex].a}</p></div>}
        <div className="flex justify-between items-center mt-6"><button type="button" onClick={()=>setPracticeMode(false)} className="text-sm text-slate-400 hover:text-white">Exit practice</button><button type="button" disabled={practiceChoice===null} onClick={nextPracticeQuestion} className="frost-btn-primary rounded-xl px-4 py-2.5 text-sm font-bold disabled:opacity-40">{practiceIndex===practiceItems.length-1?'See results':'Next question'} →</button></div>
      </div> : <div className="text-center py-7"><p className="text-4xl mb-3">{practiceScore>=8?'🏆':practiceScore>=5?'✨':'💪'}</p><h4 className="text-xl font-extrabold">You scored {practiceScore} out of {practiceItems.length}</h4><p className="text-sm text-slate-400 mt-2">Each round draws ten MCQs in a fresh random order, without repeating a question in that round.</p><div className="flex justify-center gap-3 mt-5"><button type="button" onClick={startPractice} className="frost-btn-primary rounded-xl px-4 py-2.5 text-sm font-bold"><RotateCcw className="inline w-4 h-4 mr-2"/>New round</button><button type="button" onClick={()=>setPracticeMode(false)} className="frost-btn rounded-xl px-4 py-2.5 text-sm font-bold">Back to QB</button></div></div>}
    </div>}
    <div className={practiceMode ? "hidden" : "space-y-3"}>
      {visible.map(item=><article key={item.n} className="frost-glass rounded-2xl overflow-hidden">
        <button onClick={()=>setOpen(open===item.n?null:item.n)} className="w-full p-4 sm:p-5 text-left flex justify-between gap-4 items-start hover:bg-white/[0.025]">
          <span><span className="inline-flex gap-2 items-center text-[10px] font-bold uppercase tracking-wide text-slate-400 mb-2"><span className="bg-white/10 border border-white/10 rounded-md px-2 py-1">Q{item.n}</span><span>Unit {item.unit}</span><span>·</span><span>{item.kind}</span></span><span className="block font-semibold text-sm sm:text-base leading-relaxed">{item.q}</span></span>{open===item.n?<ChevronUp className="w-4 h-4 shrink-0 mt-1"/>:<ChevronDown className="w-4 h-4 shrink-0 mt-1"/>}
        </button>
        {open===item.n && <div className="border-t border-white/10 px-4 sm:px-5 py-4 space-y-4">
          {item.choices && <ol type="a" className="grid sm:grid-cols-2 gap-x-5 gap-y-1 text-sm text-slate-400 list-[lower-alpha] pl-5">{item.choices.map((c,i)=><li key={c} className={view==='solutions'&&i===item.correct?'text-emerald-200 font-semibold':''}>{c}{view==='solutions'&&i===item.correct?' ✓':''}</li>)}</ol>}
          {view==='solutions' && <div className="rounded-xl border border-emerald-300/15 bg-emerald-300/[0.04] p-4"><h4 className="text-[11px] uppercase tracking-wider font-bold text-emerald-200 mb-2">{item.kind==='MCQ'?'Correct answer and why':'Step-by-step model answer'}</h4><p className="text-sm text-slate-200 leading-relaxed whitespace-pre-line">{item.a}</p></div>}
          {view==='questions' && <p className="text-xs text-slate-500">Switch to <button className="underline text-cyan-200" onClick={()=>setView('solutions')}>Solved QB</button> for the answer and explanation.</p>}
          {view==='solutions' && item.visual && <div className="rounded-xl border border-white/10 bg-black/20 p-4"><p className="text-[10px] uppercase tracking-wider font-bold text-slate-500 mb-3">Visual explanation</p>{diagrams[item.visual]}</div>}
        </div>}
      </article>)}
    </div>
  </section>;
};
